  '.github/workflows/build-macos.yml',
  '.github/workflows/build-mobile.yml',
  '.github/workflows/ci.yml',
];

// ── fixture helpers ────────────────────────────────────────────────────────

final _fixtureRoot = Directory.systemTemp.createTempSync('release-hygiene-');

